  const comp = asm.components.find((c) => c.part != null && m.project.parts.find((p) => p.id === c.part)?.features.some((f) => f.type === 'extrude'));
  const part = m.project.parts.find((p) => p.id === comp.part);
  const ex = part.features.filter((f) => f.type === 'extrude').at(-1);
  m.actions.change('op.config', () => { part.configurations = [...(part.configurations ?? []), { id: 'cfgShort', name: 'Short', variables: {}, suppress: { [ex.id]: true }, values: {} }]; });
