  sel.value = 'cfgShort'; sel.dispatchEvent(new Event('change', { bubbles: true })); await sleep(1200);
  return JSON.stringify({ less: inNew === all - 1, back: inDefault === all, partConfig: comp.config === 'cfgShort', configs: (asm.configurations ?? []).length });
